function setup() {
  createCanvas(windowWidth, windowHeight);
  colorMode(HSB, 360, 100, 100, 255);
  setObject();
}

let _minW;
let _maxW;
let _aryRegionRect = [];

function setObject() {
  _minW = max(width, height) * 1;
  _maxW = max(width, height) * 1;
  ellipseMode(RADIUS);
  rectMode(CENTER);
  stroke(0);
  noFill();
  strokeWeight(_minW / 400);// * pixelDensity() / 2);
  _aryRegionRect = [];
  let numRegionRect = 4;//int(random(1, 7));//int(_maxW / _minW * 40);// int(width * height / 10000);//15000);
  let minRegionX = -width / 2 * 1;
  let maxRegionX = width / 2 * 1;
  let regionHeight = _minW / numRegionRect * 0.8;
  let regionClearance = _minW / 20;
  for (let i = 0; i < numRegionRect; i++) {
    let centRegionY = -(regionHeight * numRegionRect + regionClearance * (numRegionRect - 1)) / 2 + regionHeight * (i + 0.5) + regionClearance * i;
    let minRegionY = -regionHeight / 2;
    let maxRegionY = regionHeight / 2
    let triggerX = (maxRegionX - minRegionX) * 0.5 * (-0.1 + 1 / (numRegionRect - 1) * i);
    let speedX = -_minW / 800 * 1.4**i;
    _aryRegionRect.push(new RegionRect(minRegionX, maxRegionX, minRegionY, maxRegionY, centRegionY, triggerX, speedX));
  }
}

class RegionRect {
  constructor(minRegionX, maxRegionX, minRegionY, maxRegionY, centRegionY, triggerX, speedX) {
    this.minRegionX = minRegionX;
    this.maxRegionX = maxRegionX;
    this.minRegionY = minRegionY;
    this.maxRegionY = maxRegionY;
    this.centRegionY = centRegionY;
    this.triggerX = triggerX;
    this.speedX = speedX;
    this.setPolygon();
  }

  setPolygon() {
    this.maxTrial = 100;
    let numPolygon = 10;//300;
    this.maxPolygonR = min(this.maxRegionX - this.minRegionX, this.maxRegionY - this.minRegionY) / 3
    this.stepR = _minW / 800;//500;
    this.shrink = min(this.maxRegionX - this.minRegionX, this.maxRegionY - this.minRegionY) / 50;//400;
    let palette = [];//this.setCol();
    let minX = this.triggerX;
    let maxX = this.triggerX + _minW * 0.5;
    this.addRate = 4; //frame per an object
    this.regionRotate = 0;//random([0, PI]);
    this.aryPolygon = [];
    this.aryAryCornerXy = [];
    for (let i = 0; i < numPolygon; i++) {
      let areaXy = setAreaXy(minX, maxX, this.minRegionY, this.maxRegionY);
      let rotateAng = random(2*PI);
      let numCorner = int(random(3, 7));//9));
      let numInner = int(random(1, 6));//10));
      if (i > 0) {
        let isInside = checkInside(this.aryAryCornerXy, areaXy);
        let countTrial = 0;
        let _wG_1 = 0; while ((isInside == true) && ++_wG_1 < 20000) {
          countTrial++;
          areaXy = setAreaXy(minX, maxX, this.minRegionY, this.maxRegionY);
          isInside = checkInside(this.aryAryCornerXy, areaXy);
          if (countTrial > this.maxTrial) { break; }
        }
        if(countTrial > this.maxTrial) { break; }
      }
      let aryTemp = growPolygon(numCorner, this.aryAryCornerXy, areaXy, rotateAng, this.maxPolygonR, this.stepR,
        this.minRegionX, this.maxRegionX * 2, this.minRegionY, this.maxRegionY); //maxRegionX * 2
      let aryCornerXy = aryTemp[0];
      let areaR = aryTemp[1];
      if (areaR - this.shrink > 0) {
        this.aryPolygon.push(new AreaPolygon(areaXy, areaR, rotateAng, this.shrink, palette, numInner, numCorner, this.speedX, this.triggerX));// col, col2));
        this.aryAryCornerXy.push(aryCornerXy);
      }
    }
  }

  addPolygon() {
    let minX = this.triggerX;
    let maxX = this.triggerX + _minW * 0.5;
    let areaXy = setAreaXy(minX, maxX, this.minRegionY, this.maxRegionY);
    let rotateAng = random(2*PI);
    let numCorner = int(random(3, 7));//9));
    let numInner = int(random(1, 6));//10));
    let palette = [];
    let isInside = checkInside(this.aryAryCornerXy, areaXy);
    let countTrial = 0;
    let _wG_2 = 0; while ((isInside == true) && ++_wG_2 < 20000) {
      countTrial++;
      areaXy = setAreaXy(minX, maxX, this.minRegionY, this.maxRegionY);
      isInside = checkInside(this.aryAryCornerXy, areaXy);
      if (countTrial > this.maxTrial) { break; }
    }
    if(countTrial > this.maxTrial) { return; }
    let aryTemp = growPolygon(numCorner, this.aryAryCornerXy, areaXy, rotateAng, this.maxPolygonR, this.stepR,
      this.minRegionX, this.maxRegionX * 2, this.minRegionY, this.maxRegionY); //maxRegionX * 2
    let aryCornerXy = aryTemp[0];
    let areaR = aryTemp[1];
    if (areaR - this.shrink > 0) {
      this.aryPolygon.push(new AreaPolygon(areaXy, areaR, rotateAng, this.shrink, palette, numInner, numCorner, this.speedX, this.triggerX));// col, col2));
      this.aryAryCornerXy.push(aryCornerXy);
    }
  }

  draw() {
    push();
    translate(0, this.centRegionY);
    rotate(this.regionRotate);
    for (let i = this.aryPolygon.length - 1; i >= 0; i--) {
      this.aryPolygon[i].draw();
      for (let j = 0; j < this.aryAryCornerXy[i].length; j++) {
        this.aryAryCornerXy[i][j].x += this.speedX;
      }
      if (this.aryPolygon[i].areaXy.x < (this.minRegionX - this.maxPolygonR) * 1.5) {
        this.aryPolygon.splice(i, 1);
        this.aryAryCornerXy.splice(i, 1);
      }
    }
    pop();
    if (frameCount % this.addRate == 0) { this.addPolygon(); }
  }
}

function setAreaXy(minRegionX, maxRegionX, minRegionY, maxRegionY) {
  let areaXy = createVector(random(minRegionX, maxRegionX), random() * (maxRegionY - minRegionY) + minRegionY);

  return areaXy;
}

function growPolygon(numCorner, aryAryXyPolygon, areaXy, rotateAng, maxPolygonR, stepR, minRegionX, maxRegionX, minRegionY, maxRegionY) {
  //x = center, a, b, c, ... = corner clockwise
  //grow lines a-b b-c c- ... -a until hitting other line
  let areaR = 0;
  let isCross = false;
  let stepAng = 2*PI / numCorner;
  let _wG_3 = 0; while ((isCross == false) && ++_wG_3 < 20000) {
    areaR += stepR;
    let aryCornerXy = [];
    for (let i = 0; i < numCorner; i++) {
      aryCornerXy[i] = p5.Vector.add(areaXy, createVector(0, -areaR).rotate(stepAng * (i - 0.5)).rotate(rotateAng));//side toward upper direction
    }
    for (let i = 0; i < aryAryXyPolygon.length; i++) {
      for (let j = 0; j < aryAryXyPolygon[i].length; j++) {
        let next_j = (j + 1) % aryAryXyPolygon[i].length;
        for (let k = 0; k < numCorner; k++) {
          let next_k = (k + 1) % numCorner;
          if (checkCrossLineSegment(aryCornerXy[k], aryCornerXy[next_k], aryAryXyPolygon[i][j], aryAryXyPolygon[i][next_j]) == true) {
            isCross = true;
            break;
          }
        }
        if (isCross == true) { break; }
      }
      if (isCross == true) { break; }
    }
    for (let i = 0; i < numCorner; i++) {
      if (aryCornerXy[i].x < minRegionX || aryCornerXy[i].x > maxRegionX || aryCornerXy[i].y < minRegionY || aryCornerXy[i].y > maxRegionY) {
        isCross = true;
      }
    }
    if (isCross == true) { areaR -= stepR; }
    if (areaR > maxPolygonR) {
      areaR = maxPolygonR;
      break;
    }
  }

  aryCornerXy = [];
  for (let i = 0; i < numCorner; i++) {
    aryCornerXy[i] = p5.Vector.add(areaXy, createVector(0, -areaR).rotate(stepAng * (i - 0.5)).rotate(rotateAng));//side toward upper direction
  }

  return [aryCornerXy, areaR];
}

function checkCrossLineSegment(xy_a, xy_b, xy_c, xy_d) { //line xy_a to xy_b, line xy_c to xy_d
  let isCross = false;
  let vec_a_b = p5.Vector.sub(xy_b, xy_a);
  let vec_a_c = p5.Vector.sub(xy_c, xy_a);
  let vec_a_d = p5.Vector.sub(xy_d, xy_a);
  let vec_c_d = p5.Vector.sub(xy_d, xy_c);
  let vec_c_a = p5.Vector.sub(xy_a, xy_c);
  let vec_c_b = p5.Vector.sub(xy_b, xy_c);
  let cr_ab_ac = p5.Vector.cross(vec_a_b, vec_a_c);
  let cr_ab_ad = p5.Vector.cross(vec_a_b, vec_a_d);
  let cr_cd_ca = p5.Vector.cross(vec_c_d, vec_c_a);
  let cr_cd_cb = p5.Vector.cross(vec_c_d, vec_c_b);
  if (cr_ab_ac.z * cr_ab_ad.z <= 0 && cr_cd_ca.z * cr_cd_cb.z <= 0) {
    isCross = true;
  }

  return isCross;
}

function checkInside(aryAryXy, areaXy) {
  let isInside = false;
  for (let i = 0; i < aryAryXy.length; i++) {
    for (let j = 0; j < aryAryXy[i].length; j++) {
      let next_j = (j + 1) % aryAryXy[i].length;
      let vec_a_b = p5.Vector.sub(aryAryXy[i][next_j], aryAryXy[i][j]);
      let vec_a_c = p5.Vector.sub(areaXy, aryAryXy[i][j]);
      let cr_ab_ac = p5.Vector.cross(vec_a_b, vec_a_c);
      if (cr_ab_ac.z < 0) {
        break;
      } else if (j == aryAryXy[i].length - 1) {
        isInside = true;
      }
    }
    if (isInside == true) { break; }
  }

  return isInside;
}

class AreaPolygon {
  constructor(areaXy, areaR, rotateAng, shrink, palette, numInner, numCorner, speedX, triggerX) {
    this.areaXy = areaXy;
    this.areaR = areaR;
    this.rotateAng = rotateAng;
    this.shrink = shrink;
    this.r = this.areaR - this.shrink;
    this.numCorner = numCorner;
    this.stepAng = 2*PI / this.numCorner;
    this.speedX = speedX;
    this.triggerX = triggerX;
    this.growSpeed = random(10, 20) * 6; //count per a floor
    this.count = 0;
    this.currentRatio = 0;
    this.currentCol = [];
    this.palette = palette;
    this.numInner = numInner;
    this.setInner();
  }

  setInner() {
    this.aryInnerR = [];
    this.aryInnerAng = [];
    this.aryGrad = [];
    this.aryCurrentRatio = [];
    this.aryCurrentCol = [];
    let stepR = this.r / ((this.numInner + 1) * 2 - 1) * 2;
    for (let i = 0; i < this.numInner; i++) {
      this.aryInnerR[i] = this.r - stepR * (i + 1);
      this.aryInnerAng[i] = 2*PI / this.numCorner * int(random(this.numCorner));
      this.aryCurrentRatio[i] = 0;
    }
  }

  draw() {
    this.areaXy.x += this.speedX;
    if (this.areaXy.x > this.triggerX) { return; }
    if (this.count > 0) {
      if (this.count <= this.growSpeed) {
        this.currentRatio = easing(this.growSpeed, this.count, "out", 3);//this.count / this.growSpeed;
      }
      push();
      translate(this.areaXy.x, this.areaXy.y);
      rotate(this.rotateAng);
      beginShape();
      for (let i = 0; i < this.numCorner; i++) {
        vertex(this.r * this.currentRatio * cos(this.stepAng * (i - 0.5) - PI / 2), this.r * this.currentRatio * sin(this.stepAng * (i - 0.5) - PI / 2));
      }
      endShape(CLOSE);
      pop();
      this.drawInner();
    }
    this.count++;
  }

  drawInner() {
    for (let i = 0; i < this.numInner; i++) {
      if (this.count > (i + 1) * this.growSpeed && this.count <= (i + 2) * this.growSpeed) {
        this.aryCurrentRatio[i] = easing(this.growSpeed, this.count - (i + 1) * this.growSpeed, "out", 3);
      }
      if (this.aryCurrentRatio[i] > 0) {
        push();
        translate(this.areaXy.x, this.areaXy.y);
        rotate(this.rotateAng);
        rotate(this.aryInnerAng[i]);
        beginShape();
        for (let j = 0; j < this.numCorner; j++) {
          vertex(this.aryInnerR[i] * this.aryCurrentRatio[i] * cos(this.stepAng * (j - 0.5) - PI / 2), this.aryInnerR[i] * this.aryCurrentRatio[i] * sin(this.stepAng * (j - 0.5) - PI / 2));
        }
        endShape(CLOSE);
        pop();
      }
    }
  }
}

function easing(unitTime, t, type, d) {
  let value;
  if (type == "in") {
    value = easeIn(unitTime, t, d);
  } else if (type == "out") {
    value = easeOut(unitTime, t, d);
  } else if (type == "inout") {
    value = easeInOut(unitTime, t, d);
  }

  return value;
}

function easeIn(unitTime, t, d) {
  let value = (t / unitTime)**d;

  return value;
}

function easeOut(unitTime, t, d) {
  let t2 = unitTime - t;
  let value = 1 - easeIn(unitTime, t2, d);

  return value;
}

function easeInOut(unitTime, t, d) {
  let t2;
  let value;
  if (t < unitTime / 2) {
    t2 = t * 2;
    value = easeIn(unitTime, t2, d) / 2;
  } else {
    t2 = t * 2 - unitTime;
    value = easeOut(unitTime, t2, d) / 2 + 0.5;
  }

  return value;
}

